   "  if (badge) btn.appendChild(badge);\n}\n\nasync function revisarCapacitacionPendiente() {\n  aplicarBienvenidaMenu();\n  if (_bienvenidaWeb().activa === false) return;\n  try {\n    const pendientes = await api('/api/capacitacion/pendientes');\n    const badge = document.getElementById('btnCapacitacionBadge');\n    if (pendientes.length) {\n      badge.textContent = pendientes.length;\n      badge.style.display = 'inline-block';\n      if (!CAPACITACION_PENDIENTE_POSPUESTA) abrirMiCapacitacion(true);\n    } else {\n      badge.style.display = 'none';\n    }\n  } catch (e) { /* silencioso a propósito — no bloquear el arranque de la app por esto */ }\n}\n\nasync function abrirMiCapacitacion(esAvisoObligatorio = false) {\n  document.getElementById('modalContent').innerHTML = `\n    <button class=\"close-btn\" onclick=\"cerrarModal()\">cerrar</button>\n    <h2>👋 ${escapeHtml(_bienvenidaWeb().nombre || 'Bienvenido')}${esAvisoObligatorio ? ' — capacitación pendiente' : ''}</h2>\n    ${_bienvenidaWeb().texto ? `<p style=\"font-size:13px; white-space:pre-wrap;\">${escapeHtml(_bienvenidaWeb().texto)}</p>` : ''}\n    <div id=\"misAnunciosLista\"></div>\n    <h3 style=\"font-size:14px; margin:14px 0 4px;\">📚 Capacitación</h3>\n    <p style=\"font-size:12px; color:var(--muted);\">${esAvisoObligatorio\n      ? 'Hay material que todavía no has visto o leído. Puedes posponerlo, pero seguirá pendiente hasta que lo marques como visto.'\n      : 'Todo el material de capacitación de la empresa, y cuáles ya viste o leíste.'}</p>\n    <div id=\"miCapacitacionLista\"><p style=\"font-size:12px; color:var(--muted);\">Cargando…</p></div>\n    ${esAvisoObligatorio ? `<button class=\"secondary\" style=\"width:100%; margin-top:12px;\" onclick=\"posponerCapacitacion()\">Recordarme después</button>` : ''}\n  `;\n  abrirModal(true);\n  renderMisAnuncios();\n  await renderMiCapacitacionLista();\n}\n\nasync function renderMisAnuncios() {\n",
   "  if (badge) btn.appendChild(badge);\n}\n\n// Estado de las firmas de enterado del usuario (de /api/capacitacion/mi-estado):\n// { total, firmados, por_firmar, por_ver, estado: sin_documentos|sin_firma|parcial|completo, obligatorio }\nlet BIENVENIDA_ESTADO_FIRMAS = null;\n\nconst COLORES_FIRMA_BIENVENIDA = {\n  sin_firma: { fondo: 'rgba(216,25,47,0.18)', borde: '#D8192F', texto: 'Sin firmar' },\n  parcial: { fondo: 'rgba(230,160,20,0.18)', borde: '#E6A014', texto: 'Faltan firmas' },\n  completo: { fondo: 'rgba(40,160,80,0.16)', borde: '#28A050', texto: 'Todo firmado' },\n};\n\nfunction pintarBotonBienvenida() {\n  const btn = document.getElementById('btnCapacitacion');\n  const e = BIENVENIDA_ESTADO_FIRMAS;\n  if (!btn) return;\n  let leyenda = btn.querySelector('.bienvenida-firmas');\n  const c = e && COLORES_FIRMA_BIENVENIDA[e.estado];\n  if (!c) {\n    btn.style.background = ''; btn.style.borderColor = ''; btn.style.borderWidth = '';\n    if (leyenda) leyenda.remove();\n    return;\n  }\n  btn.style.background = c.fondo;\n  btn.style.borderColor = c.borde;\n  btn.style.borderWidth = '2px';\n  if (!leyenda) {\n    leyenda = document.createElement('span');\n    leyenda.className = 'bienvenida-firmas';\n    leyenda.style.cssText = 'display:block; font-size:11px; font-weight:700; margin-top:2px;';\n    btn.appendChild(leyenda);\n  }\n  leyenda.style.color = c.borde;\n  leyenda.textContent = `✍️ ${c.texto} · ${e.firmados} de ${e.total}`;\n}\n\nasync function revisarCapacitacionPendiente() {\n  aplicarBienvenidaMenu();\n  if (_bienvenidaWeb().activa === false) return;\n  try {\n    const [pendientes, estado] = await Promise.all([\n      api('/api/capacitacion/pendientes'),\n      api('/api/capacitacion/mi-estado').catch(() => null),\n    ]);\n    BIENVENIDA_ESTADO_FIRMAS = estado;\n    pintarBotonBienvenida();\n    const badge = document.getElementById('btnCapacitacionBadge');\n    if (pendientes.length) {\n      badge.textContent = pendientes.length;\n      badge.style.display = 'inline-block';\n      const abierto = document.getElementById('overlay').classList.contains('open') && document.getElementById('miCapacitacionLista');\n      if (!abierto && (!CAPACITACION_PENDIENTE_POSPUESTA || (estado && estado.obligatorio))) abrirMiCapacitacion(true);\n    } else {\n      badge.style.display = 'none';\n    }\n  } catch (e) { /* silencioso a propósito — no bloquear el arranque de la app por esto */ }\n}\n\nfunction _resumenFirmasBienvenidaHtml() {\n  const e = BIENVENIDA_ESTADO_FIRMAS;\n  const c = e && COLORES_FIRMA_BIENVENIDA[e.estado];\n  if (!c) return '';\n  const pct = e.total ? Math.round(100 * e.firmados / e.total) : 0;\n  return `\n    <div id=\"bienvenidaResumenFirmas\" style=\"border:2px solid ${c.borde}; background:${c.fondo}; border-radius:8px; padding:10px 12px; margin:8px 0 12px;\">\n      <div style=\"font-weight:800; color:${c.borde};\">✍️ ${c.texto}: ${e.firmados} de ${e.total} documento${e.total === 1 ? '' : 's'} firmado${e.total === 1 ? '' : 's'}</div>\n      <div style=\"height:8px; background:rgba(0,0,0,0.12); border-radius:6px; margin-top:6px; overflow:hidden;\"><div style=\"height:100%; width:${pct}%; background:${c.borde};\"></div></div>\n      ${e.por_firmar ? `<div style=\"font-size:12px; margin-top:6px;\">Abre cada documento y fírmalo de enterado. ${e.obligatorio ? '<b>Es obligatorio: esta ventana no se cierra hasta que firmes todos.</b>' : ''}</div>` : ''}\n    </div>`;\n}\n\nasync function abrirMiCapacitacion(esAvisoObligatorio = false) {\n  if (!BIENVENIDA_ESTADO_FIRMAS) {\n    try { BIENVENIDA_ESTADO_FIRMAS = await api('/api/capacitacion/mi-estado'); } catch (e) { /* sin estado: se comporta como antes */ }\n  }\n  const bloqueado = !!(BIENVENIDA_ESTADO_FIRMAS && BIENVENIDA_ESTADO_FIRMAS.obligatorio);\n  document.getElementById('modalContent').innerHTML = `\n    <button class=\"close-btn\" id=\"btnCerrarBienvenida\" onclick=\"cerrarModal()\" style=\"${bloqueado ? 'display:none;' : ''}\">cerrar</button>\n    <h2>👋 ${escapeHtml(_bienvenidaWeb().nombre || 'Bienvenido')}${esAvisoObligatorio ? ' — tienes pendientes' : ''}</h2>\n    <div id=\"bienvenidaResumenCont\">${_resumenFirmasBienvenidaHtml()}</div>\n    ${_bienvenidaWeb().texto ? `<p style=\"font-size:13px; white-space:pre-wrap;\">${escapeHtml(_bienvenidaWeb().texto)}</p>` : ''}\n    <div id=\"misAnunciosLista\"></div>\n    <h3 style=\"font-size:14px; margin:14px 0 4px;\">📚 Documentos y capacitación</h3>\n    <p style=\"font-size:12px; color:var(--muted);\">${esAvisoObligatorio\n      ? 'Hay documentos que todavía no has visto o firmado de enterado.'\n      : 'Todo el material de la empresa, cuáles ya viste y cuáles ya firmaste.'}</p>\n    <div id=\"miCapacitacionLista\"><p style=\"font-size:12px; color:var(--muted);\">Cargando…</p></div>\n    <button class=\"secondary\" id=\"btnPosponerBienvenida\" style=\"width:100%; margin-top:12px; ${esAvisoObligatorio && !bloqueado ? '' : 'display:none;'}\" onclick=\"posponerCapacitacion()\">Recordarme después</button>\n  `;\n  abrirModal(true);\n  renderMisAnuncios();\n  await renderMiCapacitacionLista();\n}\n\nasync function _refrescarEstadoBienvenida() {\n  try { BIENVENIDA_ESTADO_FIRMAS = await api('/api/capacitacion/mi-estado'); } catch (e) { return; }\n  pintarBotonBienvenida();\n  const cont = document.getElementById('bienvenidaResumenCont');\n  if (cont) cont.innerHTML = _resumenFirmasBienvenidaHtml();\n  const bloqueado = !!BIENVENIDA_ESTADO_FIRMAS.obligatorio;\n  const cerrar = document.getElementById('btnCerrarBienvenida');\n  if (cerrar) cerrar.style.display = bloqueado ? 'none' : '';\n  const posponer = document.getElementById('btnPosponerBienvenida');\n  if (posponer && bloqueado) posponer.style.display = 'none';\n}\n\nasync function renderMisAnuncios() {\n"
