   "      cont.innerHTML = '<p style=\"font-size:12px; color:var(--muted);\">Todavía no hay material de capacitación cargado.</p>';\n      return;\n    }\n    cont.innerHTML = materiales.map(m => `\n      <div style=\"border:1px solid var(--line); border-radius:6px; padding:10px 12px; margin-bottom:8px; display:flex; justify-content:space-between; align-items:center; gap:10px; flex-wrap:wrap;\">\n        <div style=\"flex:1; min-width:200px;\">\n          <div style=\"font-weight:600; font-size:13px;\">${m.tipo === 'pdf' ? '📄' : '🎥'} ${escapeHtml(m.titulo)}</div>\n          ${m.descripcion ? `<div style=\"font-size:11px; color:var(--muted); margin-top:2px;\">${escapeHtml(m.descripcion)}</div>` : ''}\n          ${m.visto_en ? `<div style=\"font-size:10px; color:var(--muted); margin-top:4px;\">✅ Visto el ${new Date(m.visto_en).toLocaleString('es-MX')}</div>` : ''}\n        </div>\n        <div style=\"display:flex; gap:6px; flex-shrink:0;\">\n          <button class=\"secondary\" style=\"padding:5px 10px; font-size:12px;\" onclick=\"verMaterialCapacitacionPorId(${m.id})\">${m.tipo === 'pdf' ? 'Abrir PDF' : 'Ver video'}</button>\n          ${!m.visto_en ? `<button class=\"primary\" style=\"padding:5px 10px; font-size:12px;\" onclick=\"marcarMaterialVistoUI(${m.id}, this)\">Marcar como visto</button>` : ''}\n        </div>\n      </div>\n    `).join('');\n  } catch (e) {\n    cont.innerHTML = `<p style=\"font-size:12px; color:var(--copper);\">${escapeHtml(e.message)}</p>`;\n  }\n}\n\nfunction verMaterialCapacitacionPorId(materialId) {\n  const material = MIS_MATERIALES_CAPACITACION_CACHE.find(m => m.id === materialId);\n  if (material) verMaterialCapacitacion(material);\n}\n\nfunction _dataURItoBlobUrl(dataURI) {\n",
   "      cont.innerHTML = '<p style=\"font-size:12px; color:var(--muted);\">Todavía no hay material de capacitación cargado.</p>';\n      return;\n    }\n    cont.innerHTML = materiales.map(m => {\n      const firmado = !!m.firmado_en;\n      const colorBorde = m.requiere_firma ? (firmado ? '#28A050' : '#D8192F') : 'var(--line)';\n      const yaAbierto = !!m.visto_en || BIENVENIDA_ABIERTOS.has(m.id);\n      return `\n      <div style=\"border:1px solid var(--line); border-left:5px solid ${colorBorde}; border-radius:6px; padding:10px 12px; margin-bottom:8px; display:flex; justify-content:space-between; align-items:center; gap:10px; flex-wrap:wrap;\">\n        <div style=\"flex:1; min-width:200px;\">\n          <div style=\"font-weight:600; font-size:13px;\">${m.tipo === 'pdf' ? '📄' : '🎥'} ${escapeHtml(m.titulo)}</div>\n          ${m.descripcion ? `<div style=\"font-size:11px; color:var(--muted); margin-top:2px;\">${escapeHtml(m.descripcion)}</div>` : ''}\n          ${m.visto_en ? `<div style=\"font-size:10px; color:var(--muted); margin-top:4px;\">👁️ Visto el ${new Date(m.visto_en).toLocaleString('es-MX')}</div>` : ''}\n          ${m.requiere_firma ? (firmado\n            ? `<div style=\"font-size:11px; color:#28A050; font-weight:700; margin-top:4px;\">✍️ Firmado de enterado el ${new Date(m.firmado_en).toLocaleString('es-MX')}${m.firma_nombre ? ` por ${escapeHtml(m.firma_nombre)}` : ''}</div>`\n            : `<div style=\"font-size:11px; color:#D8192F; font-weight:700; margin-top:4px;\">✍️ Falta tu firma de enterado${yaAbierto ? '' : ' — ábrelo primero'}</div>`) : ''}\n        </div>\n        <div style=\"display:flex; gap:6px; flex-shrink:0; flex-wrap:wrap;\">\n          <button class=\"secondary\" style=\"padding:5px 10px; font-size:12px;\" onclick=\"verMaterialCapacitacionPorId(${m.id})\">${m.tipo === 'pdf' ? 'Abrir PDF' : 'Ver video'}</button>\n          ${m.requiere_firma && !firmado\n            ? `<button class=\"primary\" style=\"padding:5px 10px; font-size:12px; ${yaAbierto ? '' : 'opacity:0.5;'}\" onclick=\"abrirFirmaEnterado(${m.id})\">✍️ Firmar de enterado</button>`\n            : (!m.requiere_firma && !m.visto_en ? `<button class=\"primary\" style=\"padding:5px 10px; font-size:12px;\" onclick=\"marcarMaterialVistoUI(${m.id}, this)\">Marcar como visto</button>` : '')}\n        </div>\n      </div>`;\n    }).join('');\n  } catch (e) {\n    cont.innerHTML = `<p style=\"font-size:12px; color:var(--copper);\">${escapeHtml(e.message)}</p>`;\n  }\n}\n\n// Documentos que se abrieron en esta sesión (para habilitar \"Firmar\" sin\n// esperar la respuesta del servidor).\nconst BIENVENIDA_ABIERTOS = new Set();\n\nfunction verMaterialCapacitacionPorId(materialId) {\n  const material = MIS_MATERIALES_CAPACITACION_CACHE.find(m => m.id === materialId);\n  if (!material) return;\n  verMaterialCapacitacion(material);\n  // Abrirlo cuenta como \"visto\" (va DESPUÉS del window.open para no\n  // romper el clic — ver nota en db.mis_materiales_capacitacion).\n  const nuevo = !material.visto_en && !BIENVENIDA_ABIERTOS.has(materialId);\n  BIENVENIDA_ABIERTOS.add(materialId);\n  if (nuevo) {\n    api(`/api/capacitacion/${materialId}/marcar-visto`, { method: 'POST' })\n      .then(() => { material.visto_en = new Date().toISOString(); })\n      .catch(() => {});\n    if (material.tipo !== 'video') setTimeout(() => { if (document.getElementById('miCapacitacionLista')) renderMiCapacitacionLista(); }, 400);\n  }\n}\n\n// ---- Firma de enterado ----\nlet firmaEnteradoCtx = null, firmaEnteradoDibujando = false, firmaEnteradoVacia = true;\n\nfunction abrirFirmaEnterado(materialId) {\n  const m = MIS_MATERIALES_CAPACITACION_CACHE.find(x => x.id === materialId);\n  if (!m) return;\n  if (!m.visto_en && !BIENVENIDA_ABIERTOS.has(materialId)) {\n    alert('Primero abre el documento (botón \"' + (m.tipo === 'pdf' ? 'Abrir PDF' : 'Ver video') + '\") y revísalo; después lo firmas.');\n    return;\n  }\n  const cont = document.getElementById('miCapacitacionLista');\n  const fecha = new Date().toLocaleDateString('es-MX', { day: 'numeric', month: 'long', year: 'numeric' });\n  cont.innerHTML = `\n    <button class=\"secondary\" style=\"margin-bottom:10px;\" onclick=\"renderMiCapacitacionLista()\">← Volver a la lista</button>\n    <div style=\"border:2px solid #D8192F; border-radius:8px; padding:12px;\">\n      <div style=\"font-weight:800; font-size:14px; margin-bottom:6px;\">✍️ Firma de enterado</div>\n      <div style=\"font-size:13px; margin-bottom:10px;\">\n        Declaro que recibí, ${m.tipo === 'pdf' ? 'leí' : 'vi'} y entendí el documento\n        <b>«${escapeHtml(m.titulo)}»</b>, y me comprometo a cumplir con lo que indica.\n        <div style=\"font-size:11px; color:var(--muted); margin-top:4px;\">Fecha: ${fecha}</div>\n      </div>\n      <div class=\"field\"><label>Tu nombre completo</label><input id=\"firmaEnteradoNombre\" value=\"${escapeHtml((SESION && SESION.usuario && SESION.usuario.nombre) || '')}\" /></div>\n      <label style=\"font-size:12px;\">Firma con el dedo o el mouse</label>\n      <canvas id=\"firma_enterado_canvas\" width=\"600\" height=\"180\" style=\"width:100%; height:180px; background:#fff; border:1px solid rgba(155,157,159,0.6); border-radius:6px; touch-action:none; cursor:crosshair; margin-top:4px;\"></canvas>\n      <div style=\"display:flex; gap:8px; margin-top:8px;\">\n        <button class=\"secondary\" onclick=\"limpiarFirmaEnterado()\">Borrar</button>\n        <button class=\"primary\" style=\"flex:1;\" onclick=\"guardarFirmaEnterado(${m.id}, this)\">Firmar de enterado</button>\n      </div>\n      <div id=\"firmaEnteradoError\" class=\"error-msg\"></div>\n    </div>`;\n  const canvas = document.getElementById('firma_enterado_canvas');\n  firmaEnteradoCtx = canvas.getContext('2d');\n  firmaEnteradoCtx.fillStyle = '#fff';\n  firmaEnteradoCtx.fillRect(0, 0, canvas.width, canvas.height);\n  firmaEnteradoCtx.strokeStyle = '#1a1a1a';\n  firmaEnteradoCtx.lineWidth = 2.5;\n  firmaEnteradoCtx.lineCap = 'round';\n  firmaEnteradoCtx.lineJoin = 'round';\n  firmaEnteradoVacia = true;\n  const pos = (e) => {\n    const r = canvas.getBoundingClientRect();\n    const p = e.touches ? e.touches[0] : e;\n    return { x: (p.clientX - r.left) * (canvas.width / r.width), y: (p.clientY - r.top) * (canvas.height / r.height) };\n  };\n  const empezar = (e) => { e.preventDefault(); firmaEnteradoDibujando = true; const p = pos(e); firmaEnteradoCtx.beginPath(); firmaEnteradoCtx.moveTo(p.x, p.y); };\n  const dibujar = (e) => { if (!firmaEnteradoDibujando) return; e.preventDefault(); firmaEnteradoVacia = false; const p = pos(e); firmaEnteradoCtx.lineTo(p.x, p.y); firmaEnteradoCtx.stroke(); };\n  const terminar = () => { firmaEnteradoDibujando = false; };\n  canvas.onmousedown = empezar; canvas.onmousemove = dibujar; canvas.onmouseup = terminar; canvas.onmouseleave = terminar;\n  canvas.ontouchstart = empezar; canvas.ontouchmove = dibujar; canvas.ontouchend = terminar;\n}\n\nfunction limpiarFirmaEnterado() {\n  const canvas = document.getElementById('firma_enterado_canvas');\n  if (!canvas || !firmaEnteradoCtx) return;\n  firmaEnteradoCtx.fillStyle = '#fff';\n  firmaEnteradoCtx.fillRect(0, 0, canvas.width, canvas.height);\n  firmaEnteradoVacia = true;\n}\n\nasync function guardarFirmaEnterado(materialId, boton) {\n  const err = document.getElementById('firmaEnteradoError');\n  const nombre = document.getElementById('firmaEnteradoNombre').value.trim();\n  if (nombre.length < 3) { err.textContent = 'Escribe tu nombre completo'; return; }\n  if (firmaEnteradoVacia) { err.textContent = 'Firma en el recuadro'; return; }\n  const firma = document.getElementById('firma_enterado_canvas').toDataURL('image/png');\n  await conBloqueoDeBoton(boton, async () => {\n    try {\n      await api(`/api/capacitacion/${materialId}/firmar`, { method: 'POST', body: JSON.stringify({ firma_base64: firma, nombre, origen: 'web' }) });\n      mostrarExito('¡Firmado! Gracias.');\n      await renderMiCapacitacionLista();\n      await _refrescarEstadoBienvenida();\n      await revisarCapacitacionPendiente();\n    } catch (e) {\n      err.textContent = e.message;\n    }\n  });\n}\n\nfunction _dataURItoBlobUrl(dataURI) {\n"
